=:root {
	/* Typography */
	--font-family: 'Open Sans', Arial, sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 700;

	--font-size-body: 14px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 15px;
	--font-size-header: 28px;
	--font-size-paragraph: 15px;
	--font-size-link: 13px;
	--font-size-error: 12px;

	--font-size-html-h1: 30px;
	--font-size-html-h2: 22px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 16px;
	--font-size-html-h5: 14px;
	--font-size-html-h6: 12px;
	--font-size-subheader: 15px;


	/* Colors */
	--color-background: #cceaff;

	--color-test-notice-text: #805e00;
	--color-test-notice-bg: rgba(255,255,255,0.80);
	--color-test-notice-border: rgba(255,255,255,0.70);

	--color-card-bg: rgba(255,255,255,0.86);
	--color-card-border: rgba(255,255,255,0.70);
	--color-card-shadow: rgba(31,78,121,0.18);

	--color-link: #2f80ed;

	--color-header: #173956;
	--color-label: #395c78;

	--color-input-border: #c9dcec;
	--color-input-text: #173956;

	--color-focus-border: #2f80ed;

	--color-submit-btn-bg: #2f80ed;
	--color-submit-btn-text: #ffffff;

	--color-error: #dc3545;
	--color-required: #dc3545;

	--color-clear-button-bg: #71879a;

	--color-html-text: #24435f;
	--color-html-link: #2f80ed;
	--color-header-subtext: #6f879b;


	/* Rounded corners */
	--border-radius-card: 26px;
	--border-radius-input: 12px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 26px;


	/* Spacing */
	--padding-container-top: 55px;
	--padding-card: 32px;

	--padding-test-notice-vertical: 10px;
	--padding-test-notice-horizontal: 20px;

	--margin-bottom-card: 20px;

	--padding-form-input: 14px;

	--card-padding: 32px;
	--card-margin-bottom: 20px;


	/* Dimensions */
	--container-width: 580px;
	--submit-btn-height: 52px;
	--checkbox-size: 18px;


	/* Effects */
	--box-shadow-card:
		0px 20px 55px rgba(31,78,121,0.18);

	--opacity-placeholder: 0.55;
}


/* Sky Background */
body {
	background:
		radial-gradient(circle at 12% 18%,
			rgba(255,255,255,0.90) 0 48px,
			transparent 49px),

		radial-gradient(circle at 20% 20%,
			rgba(255,255,255,0.75) 0 35px,
			transparent 36px),

		radial-gradient(circle at 82% 15%,
			rgba(255,255,255,0.90) 0 50px,
			transparent 51px),

		radial-gradient(circle at 74% 18%,
			rgba(255,255,255,0.75) 0 36px,
			transparent 37px),

		linear-gradient(
			180deg,
			#78bdf2 0%,
			#b8dff8 48%,
			#eef8ff 100%
		);

	min-height: 100vh;
}


/* Input look */
input,
textarea,
select {
	background: rgba(255,255,255,0.82) !important;
	border-radius: 12px !important;
	transition: 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
	box-shadow: 0 0 0 3px rgba(47,128,237,0.12) !important;
}


/* Submit button */
button[type="submit"] {
	border-radius: 14px !important;
	font-weight: 700 !important;

	box-shadow:
		0 10px 24px rgba(47,128,237,0.25) !important;

	transition: transform 0.2s ease,
	            box-shadow 0.2s ease;
}

button[type="submit"]:hover {
	transform: translateY(-2px);

	box-shadow:
		0 14px 28px rgba(47,128,237,0.32) !important;
}

parameters.responseText:
={{ `
<style>
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    min-height: 100vh;
    font-family: Arial, sans-serif;
    background:
      radial-gradient(circle at 15% 18%, rgba(255,255,255,0.85) 0 45px, transparent 46px),
      radial-gradient(circle at 22% 20%, rgba(255,255,255,0.75) 0 35px, transparent 36px),
      radial-gradient(circle at 80% 15%, rgba(255,255,255,0.85) 0 50px, transparent 51px),
      radial-gradient(circle at 72% 18%, rgba(255,255,255,0.75) 0 35px, transparent 36px),
      linear-gradient(180deg, #78bdf2 0%, #b9ddf7 45%, #eef8ff 100%);
  }

  .weather-wrapper {
    width: 100%;
    display: flex;
    justify-content: center;
    padding: 35px 15px;
  }

  .weather-card {
    width: 100%;
    max-width: 580px;
    background: rgba(255,255,255,0.82);
    border: 1px solid rgba(255,255,255,0.65);
    border-radius: 28px;
    padding: 30px;
    box-shadow: 0 20px 55px rgba(31, 78, 121, 0.18);
    backdrop-filter: blur(12px);
  }

  .top {
    text-align: center;
    margin-bottom: 25px;
  }

  .weather-icon {
    font-size: 55px;
    margin-bottom: 8px;
  }

  .title {
    margin: 0;
    font-size: 30px;
    color: #173956;
    font-weight: 700;
  }

  .subtitle {
    margin-top: 6px;
    color: #6f879b;
    font-size: 14px;
  }

  .location {
    text-align: center;
    background: rgba(255,255,255,0.72);
    padding: 17px;
    border-radius: 18px;
    margin-bottom: 22px;
  }

  .city {
    font-size: 27px;
    font-weight: 700;
    color: #173956;
  }

  .country {
    margin-top: 4px;
    color: #6b8298;
    font-size: 15px;
  }

  .temperature-box {
    text-align: center;
    margin: 25px 0;
  }

  .temperature {
    display: inline-flex;
    align-items: flex-start;
    justify-content: center;
    color: white;
    background: linear-gradient(135deg, #2f80ed, #56b4f5);
    min-width: 170px;
    min-height: 150px;
    border-radius: 28px;
    padding: 30px 25px;
    box-shadow: 0 14px 28px rgba(47,128,237,0.25);
  }

  .temp-number {
    font-size: 50px;
    font-weight: 700;
  }

  .temp-unit {
    font-size: 20px;
    margin-top: 6px;
  }

  .weather-condition {
    text-align: center;
    font-size: 23px;
    color: #244b6d;
    font-weight: 600;
    margin-bottom: 24px;
  }

  .details {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
  }

  .detail-card {
    background: rgba(255,255,255,0.80);
    border-radius: 17px;
    padding: 17px;
    display: flex;
    gap: 12px;
    align-items: center;
    box-shadow: 0 6px 18px rgba(41,83,121,0.07);
  }

  .detail-icon {
    font-size: 26px;
  }

  .detail-label {
    font-size: 12px;
    color: #7a8fa2;
    margin-bottom: 4px;
  }

  .detail-value {
    font-size: 17px;
    font-weight: 700;
    color: #24435f;
  }

  .footer {
    text-align: center;
    margin-top: 24px;
    font-size: 12px;
    color: #8294a4;
  }

  @media (max-width: 520px) {
    .weather-card {
      padding: 20px;
    }

    .details {
      grid-template-columns: 1fr;
    }

    .title {
      font-size: 26px;
    }

    .temp-number {
      font-size: 44px;
    }
  }
</style>

<div class="weather-wrapper">
  <div class="weather-card">

    <div class="top">
      <div class="weather-icon">🌤️</div>
      <h1 class="title">Today Weather</h1>
      <div class="subtitle">Current weather information</div>
    </div>

    <div class="location">
      <div class="city">${$json.city}</div>
      <div class="country">${$json.country}</div>
    </div>

    <div class="temperature-box">
      <div class="temperature">
        <span class="temp-number">${$json.temperature}</span>
        <span class="temp-unit">°C</span>
      </div>
    </div>

    <div class="weather-condition">
      ${$json.weather}
    </div>

    <div class="details">

      <div class="detail-card">
        <div class="detail-icon">💧</div>
        <div>
          <div class="detail-label">Humidity</div>
          <div class="detail-value">${$json.humidity}%</div>
        </div>
      </div>

      <div class="detail-card">
        <div class="detail-icon">📍</div>
        <div>
          <div class="detail-label">City</div>
          <div class="detail-value">${$json.city}</div>
        </div>
      </div>

      <div class="detail-card">
        <div class="detail-icon">🌍</div>
        <div>
          <div class="detail-label">Country</div>
          <div class="detail-value">${$json.country}</div>
        </div>
      </div>

      <div class="detail-card">
        <div class="detail-icon">☁️</div>
        <div>
          <div class="detail-label">Condition</div>
          <div class="detail-value">${$json.weather}</div>
        </div>
      </div>

    </div>

    <div class="footer">
      Weather information generated automatically
    </div>

  </div>
</div>
` }}
